CREATE TABLE IF NOT EXISTS property_transactions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),offer_id UUID NOT NULL UNIQUE REFERENCES property_offers(id) ON DELETE RESTRICT,listing_id UUID NOT NULL REFERENCES property_listings(id) ON DELETE RESTRICT,property_id UUID NOT NULL REFERENCES properties(id) ON DELETE RESTRICT,buyer_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,seller_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,agent_id UUID REFERENCES users(id) ON DELETE SET NULL,status TEXT NOT NULL CHECK(status IN ('OPEN','CONDITIONAL','IN_TRANSFER','COMPLETED','CANCELLED')),notes TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS transaction_milestones(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),transaction_id UUID NOT NULL REFERENCES property_transactions(id) ON DELETE CASCADE,key TEXT NOT NULL,label TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('PENDING','IN_PROGRESS','COMPLETED','BLOCKED')),notes TEXT,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(transaction_id,key));
CREATE INDEX IF NOT EXISTS property_transactions_buyer_idx ON property_transactions(buyer_id); CREATE INDEX IF NOT EXISTS property_transactions_seller_idx ON property_transactions(seller_id); CREATE INDEX IF NOT EXISTS property_transactions_agent_idx ON property_transactions(agent_id);